#!/usr/bin/env python3
"""Compile only verified one-shot detector and prompt-mask pilot results."""
import argparse,json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from scripts.memory_token_io import digest,validate_output

def read(p):return json.loads(p.read_text())
p=argparse.ArgumentParser()
for k in ('training-verification','dataset-verification','box-audit','box-verification','mask-audit','mask-verification','output'):p.add_argument('--'+k,type=Path,required=True)
a=p.parse_args();t=read(a.training_verification/'verification.json');dv=read(a.dataset_verification/'verification.json');b=read(a.box_audit/'results.json');bv=read(a.box_verification/'verification.json');m=read(a.mask_audit/'results.json');mv=read(a.mask_verification/'verification.json')
if not all(x['passed'] for x in (t,dv,bv,mv)) or t['verifier_sha256']!=digest(ROOT/'scripts/verify_polypgen_one_shot_training.py') or dv['verifier_sha256']!=digest(ROOT/'scripts/verify_polypgen_detector_pilot_dataset.py') or bv['verifier_sha256']!=digest(ROOT/'scripts/verify_polypgen_one_shot_boxes.py') or mv['verifier_sha256']!=digest(ROOT/'scripts/verify_polypgen_one_shot_mask_scores.py') or bv['audit_sha256']!=digest(a.box_audit/'results.json') or mv['audit_sha256']!=digest(a.mask_audit/'results.json') or t['dataset_sha256']!=dv['dataset_sha256'] or m['box_audit_sha256']!=bv['audit_sha256']:raise ValueError('Audit evidence changed')
lines=['# One-shot detector and prompt-mask pilot','','The new detector starts from the official COCO YOLOv8n checkpoint and was trained for 20 epochs on curated PolypGen still images from C1–C5; C6 was used for model validation and checkpoint selection. The original detector was trained on an unknown split. Exact single-image/video frame matching found no duplicates, but nearby frames, re-encodings and patient overlap remain unverified. MPS training is not claimed to be bitwise reproducible.','','The detector is run once on each originally selected automatic initialization frame using the original detector confidence, IoU and image-size settings. A missing detection does not trigger another search. Seq23 is cropped to its existing inset-free viewport before model inference. All target predictions are frozen and repeated before labels are opened. These four previously inspected frames are exploratory; empty labels may be incomplete.','','| Sequence | Frame | Label | Original / candidate detection | Original / candidate box IoU | Original / candidate label coverage |','| --- | ---: | --- | :---: | ---: | ---: |']
fmt=lambda x:'—' if x is None else f'{x:.4f}'
for r in b['results']:
 old=r['original'];new=r['candidate'];lines.append(f"| {r['sequence']} | {r['frame']} | {'present' if r['present'] else 'empty'} | {'yes' if old['detected'] else 'no'} / {'yes' if new['detected'] else 'no'} | {fmt(old['box_iou'])} / {fmt(new['box_iou'])} | {fmt(old['box_truth_coverage'])} / {fmt(new['box_truth_coverage'])} |")
lines+=['','## Matched SAM2 image-prompt masks','','The saved Lean prompt uses the original video predictor. Other masks use the same author SAM2 image predictor, once with each detector box and once with feature-selected points appended. Image-predictor preprocessing differs from the video predictor. Ground-truth-box oracle masks are not available during automatic inference.','','| Sequence | Label | Saved Lean prompt Dice | Original box / points Dice | Candidate box / points Dice | Oracle box Dice | Labeled-empty false alarm: saved / old box / new box |','| --- | --- | ---: | ---: | ---: | ---: | ---: |']
for r in m['results']:
 s=r['scores'];f=lambda q:'—' if q is None or q['dice'] is None else f"{q['dice']:.4f}";fa='—' if r['present'] else ' / '.join('yes' if s[k]['false_alarm'] else 'no' for k in ('saved_lean_prompt','original_box','candidate_box'))
 lines.append(f"| {r['sequence']} | {'present' if r['present'] else 'empty'} | {f(s['saved_lean_prompt'])} | {f(s['original_box'])} / {f(s['original_points'])} | {f(s['candidate_box'])} / {f(s['candidate_points'])} | {f(s['oracle_box'])} | {fa} |")
lines+=['',f"The best reported C6 validation mAP50–95 during training was {t['validation_max_map50_95']:.4f}; that center selected the checkpoint and is not an independent final test. These image-level checks do not establish a full-video improvement, an automatic recovery after a missed prompt, or patient-level generalization. Historical GT-prompt native/Lean results use different initializations and are not matched automatic baselines.",'']
out=validate_output(a.output);out.mkdir(parents=True,exist_ok=False);(out/'report.md').write_text('\n'.join(lines));(out/'completion.json').write_text(json.dumps({'passed':True,'report_sha256':digest(out/'report.md'),'runner_sha256':digest(Path(__file__))},indent=2)+'\n');print('\n'.join(lines))
